RemoteOperation::Permission {
    run_id, capability, scope, ..
} => {
    if self.host.pending_permission() != Some((run_id.as_str(), capability)) {
        return RemoteAiStudioResponse::error(
            409,
            "permission_stale",
            "The permission request no longer matches the Agent Host pending decision.",
            false,
        );
    }
    let Some(pending) = self.pending_permission.as_ref() else {
        return RemoteAiStudioResponse::error(
            409,
            "permission_continuation_unavailable",
            "The local continuation for this permission request is unavailable.",
            false,
        );
    };
    if pending.run_id != run_id || pending.capability != capability {
        return RemoteAiStudioResponse::error(409, "permission_stale", "The permission request no longer matches the active continuation.", false);
    }
    let action = pending.action;
